/** ThreadCreatedEvent reports a new message thread. */
export interface ThreadCreatedEvent {
  roomId: string
  threadRootEventId: string
}

/** ThreadViewerStateChangedEvent reports the caller's current thread state. */
export interface ThreadViewerStateChangedEvent {
  roomId: string
  threadRootEventId: string
  isFollowing: boolean
}

/** UserAccountCreatedEvent reports a new public user account. */
export interface UserAccountCreatedEvent {
  userId: string
  isBot: boolean
}

/** Reports a reversible account access change. Administrative details are private. */
export interface UserAccountDeactivationChangedEvent {
  userId: string
  deactivated: boolean
}

/** UserAccountDeletedEvent reports a deleted user account. */
export interface UserAccountDeletedEvent {
  userId: string
}

/** UserJoinedRoomEvent reports that the actor joined a room. */
export interface UserJoinedRoomEvent {
  roomId: string
}

/** UserLeftRoomEvent reports that the actor left a room. */
export interface UserLeftRoomEvent {
  roomId: string
}

/** UserProfileChangedEvent reports that the current public user resource changed.
 * Read the user through UserService with this event's resume cursor as the
 * minimum boundary. */
export interface UserProfileChangedEvent {
  userId: string
}

/** UserTypingEvent reports current typing activity for the event actor.
 * Track each actor separately for each room and thread. Clear the indicator
 * 6 seconds after the last received typing event, or when that actor posts
 * a message in the same room or thread. No stop-typing event is sent. */
export interface UserTypingEvent {
  roomId: string
  threadRootEventId?: string
}

/** The authenticated viewer's permission decisions may have changed. This also
 * covers changes to a bot's owner permission ceiling. Delivered only to the
 * affected viewer. Discard private cached data and load current authorized
 * state before displaying it again. The connection itself remains open. */
export interface ViewerPermissionsChangedEvent {
}

/** ViewerPreferencesChangedEvent reports that the caller's private user
 * preferences changed. Read ViewerService with this event's resume cursor as
 * the minimum boundary. */
export interface ViewerPreferencesChangedEvent {
}

/** Delivered only to the account whose private availability choice changed.
 * Refetch MyAccountService.GetPresencePreference to obtain the current choice. */
export interface ViewerPresencePreferenceChangedEvent {
}

/** VoiceCallEndedEvent reports the end of a call session. */
export interface VoiceCallEndedEvent {
  roomId: string
  callId: string
}

/** VoiceCallParticipantJoinedEvent reports that the actor joined a call session. */
export interface VoiceCallParticipantJoinedEvent {
  roomId: string
  callId: string
}

/** VoiceCallParticipantLeftEvent reports that the actor left a call session. */
export interface VoiceCallParticipantLeftEvent {
  roomId: string
  callId: string
}

/** VoiceCallStartedEvent reports a new call session. */
export interface VoiceCallStartedEvent {
  roomId: string
  callId: string
}

/** Every realtime event variant, keyed by its camelCase oneof case name. */
export interface RealtimeEventPayloads {
  roomCreated: RoomCreatedEvent
  roomUpdated: RoomUpdatedEvent
  roomDeleted: RoomDeletedEvent
  roomArchived: RoomArchivedEvent
  roomUnarchived: RoomUnarchivedEvent
  roomUniversalChanged: RoomUniversalChangedEvent
  roomSlowModeChanged: RoomSlowModeChangedEvent
  roomThreadingModeChanged: RoomThreadingModeChangedEvent
  userJoinedRoom: UserJoinedRoomEvent
  userLeftRoom: UserLeftRoomEvent
  voiceCallParticipantJoined: VoiceCallParticipantJoinedEvent
  voiceCallParticipantLeft: VoiceCallParticipantLeftEvent
  voiceCallStarted: VoiceCallStartedEvent
  voiceCallEnded: VoiceCallEndedEvent
  messagePosted: MessagePostedEvent
  messageEdited: MessageEditedEvent
  messageRetracted: MessageRetractedEvent
  messagePinned: MessagePinnedEvent
  messageUnpinned: MessageUnpinnedEvent
  threadCreated: ThreadCreatedEvent
  assetProcessingStarted: AssetProcessingStartedEvent
  assetProcessingSucceeded: AssetProcessingSucceededEvent
  assetProcessingFailed: AssetProcessingFailedEvent
  assetDeleted: AssetDeletedEvent
  serverMotdChanged: ServerMotdChangedEvent
  userAccountCreated: UserAccountCreatedEvent
  userProfileChanged: UserProfileChangedEvent
  userAccountDeleted: UserAccountDeletedEvent
  reactionAdded: ReactionAddedEvent
  reactionRemoved: ReactionRemovedEvent
  viewerPreferencesChanged: ViewerPreferencesChangedEvent
  threadViewerStateChanged: ThreadViewerStateChangedEvent
  serverProfileChanged: ServerProfileChangedEvent
  userTyping: UserTypingEvent
  presenceChanged: PresenceChangedEvent
  notificationOccurrencesChanged: NotificationOccurrencesChangedEvent
  notificationUnreadStateChanged: NotificationUnreadStateChangedEvent
  roomReadStateChanged: RoomReadStateChangedEvent
  roomLayoutChanged: RoomLayoutChangedEvent
  roleCreated: RoleCreatedEvent
  roleUpdated: RoleUpdatedEvent
  roleDeleted: RoleDeletedEvent
  rolesReordered: RolesReorderedEvent
  roleAssigned: RoleAssignedEvent
  roleRevoked: RoleRevokedEvent
  rolePermissionsChanged: RolePermissionsChangedEvent
  viewerPermissionsChanged: ViewerPermissionsChangedEvent
  viewerPresencePreferenceChanged: ViewerPresencePreferenceChangedEvent
  roomInvitationCreated: RoomInvitationCreatedEvent
  roomInvitationAccepted: RoomInvitationAcceptedEvent
  roomInvitationDeclined: RoomInvitationDeclinedEvent
  roomNoticeChanged: RoomNoticeChangedEvent
  userAccountDeactivationChanged: UserAccountDeactivationChangedEvent
  roomMembershipEventsVisibilityChanged: RoomMembershipEventsVisibilityChangedEvent
}

